import { field, select, checkbox, htmlEscape } from "../tool-core.js";export default {form: `<div class="field-grid">${field({ id: "ttPolicyName", label: "Policy name", value: "default" })}${select({ id: "ttMode", label: "Enforcement mode", options: [{label:"Enforce (block violations)",value:"enforce"},{label:"Report-only (log violations)",value:"report"},{label:"Both headers",value:"both"}], value: "enforce" })}</div><hr style="margin:10px 0;border:none;border-top:1px solid var(--border,#d1d5db)"><p style="font-size:13px;font-weight:600;margin-bottom:8px">Allowed operations:</p><div class="field-grid">${checkbox({ id: "ttCreateHTML", label: "createHTML (innerHTML, insertAdjacentHTML)", checked: true })}${checkbox({ id: "ttCreateScript", label: "createScript (script.textContent, eval)", checked: false })}${checkbox({ id: "ttCreateScriptURL", label: "createScriptURL (script.src)", checked: true })}</div><hr style="margin:10px 0;border:none;border-top:1px solid var(--border,#d1d5db)"><div class="field-grid">${field({ id: "ttReportUri", label: "Report-uri (for report-only)", value: "/csp-report" })}${checkbox({ id: "ttRequireForScript", label: "Use 'require-trusted-types-for 'script''", checked: true })}</div>`,generate(root) {const policyName = root.querySelector("#ttPolicyName").value.trim() || "default";const mode = root.querySelector("#ttMode").value;const createHTML = root.querySelector("#ttCreateHTML").checked;const createScript = root.querySelector("#ttCreateScript").checked;const createScriptURL = root.querySelector("#ttCreateScriptURL").checked;const reportUri = root.querySelector("#ttReportUri").value.trim() || "/csp-report";const requireForScript = root.querySelector("#ttRequireForScript").checked;const lines = [];lines.push("// Trusted Types Policy — Baseline 2026");lines.push("// Prevents DOM-based XSS by restricting dangerous DOM sink usage.");lines.push("// Browser support: Chrome 83+, Edge 83+, Safari 17+, Firefox ✗ (planned)");lines.push("");lines.push("/* === JavaScript: Trusted Types Policy === */");lines.push("if (window.trustedTypes && trustedTypes.createPolicy) {");lines.push(` const ${policyName}Policy = trustedTypes.createPolicy('${policyName}', {`);if (createHTML) {lines.push(" createHTML: (input) => {");lines.push(" // Sanitize HTML before allowing it as innerHTML");lines.push(" // Use DOMPurify or the Sanitizer API here");lines.push(" return sanitizeHTML(input);");lines.push(" },");}if (createScript) {lines.push(" createScript: (input) => {");lines.push(" // Only allow pre-approved script content");lines.push(" throw new TypeError('Dynamic scripts not allowed');");lines.push(" },");}if (createScriptURL) {lines.push(" createScriptURL: (input) => {");lines.push(" // Only allow same-origin and approved CDN script URLs");lines.push(" const url = new URL(input, document.baseURI);");lines.push(" const allowed = [self.origin, 'https://cdnjs.cloudflare.com'];");lines.push(" if (!allowed.some(o => url.origin === o)) {");lines.push(" throw new TypeError('Script URL not allowed: ' + url.origin);");lines.push(" }");lines.push(" return input;");lines.push(" },");}lines.push(" });");lines.push("}");lines.push("");lines.push("/* === HTTP Headers === */");lines.push("");if (requireForScript) {if (mode === "enforce" || mode === "both") {lines.push("# Enforce mode (Nginx)");lines.push("add_header Content-Security-Policy \"require-trusted-types-for 'script'; trusted-types " + policyName + "\";");lines.push("");lines.push("# Enforce mode (Apache)");lines.push("Header set Content-Security-Policy \"require-trusted-types-for 'script'; trusted-types " + policyName + "\"");lines.push("");}if (mode === "report" || mode === "both") {lines.push("# Report-only mode (Nginx)");lines.push("add_header Content-Security-Policy-Report-Only \"require-trusted-types-for 'script'; trusted-types " + policyName + "; report-uri " + reportUri + "\";");lines.push("");lines.push("# Report-only mode (Apache)");lines.push("Header set Content-Security-Policy-Report-Only \"require-trusted-types-for 'script'; trusted-types " + policyName + "; report-uri " + reportUri + "\"");lines.push("");}} else {if (mode === "enforce" || mode === "both") {lines.push("add_header Content-Security-Policy \"trusted-types " + policyName + "\";");}if (mode === "report" || mode === "both") {lines.push("add_header Content-Security-Policy-Report-Only \"trusted-types " + policyName + "; report-uri " + reportUri + "\";");}}lines.push("");lines.push("# Raw CSP directive values:");if (requireForScript) lines.push("# require-trusted-types-for 'script'; trusted-types " + policyName);else lines.push("# trusted-types " + policyName);lines.push("");lines.push("# Notes:");lines.push("# 1. Trusted Types prevents DOM XSS by requiring typed values instead of strings for dangerous sinks.");lines.push("# 2. Without a policy, setting innerHTML, eval(), or script.src will throw a TypeError.");lines.push("# 3. Use 'default' as the policy name with allowDuplicates: true for a catch-all policy.");lines.push("# 4. The Sanitizer API (setHTML) works with Trusted Types: element.setHTML(html, { sanitizer });");lines.push("# 5. Test with ?trusted-types-debug in Chrome DevTools for violation reports.");const previewOps = [];if (createHTML) previewOps.push("createHTML");if (createScript) previewOps.push("createScript");if (createScriptURL) previewOps.push("createScriptURL");const preview = `<div style="border:1px solid ${mode === "enforce" ? "#dc2626" : "#f59e0b"};border-radius:10px;padding:16px;background:#f9fafb"><div style="font-size:13px;font-weight:600;margin-bottom:8px;color:#374151">Policy: <code>${policyName}</code> (${mode})</div><div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:8px">${previewOps.map(op => `<span style="background:#dcfce7;color:#166534;padding:2px 8px;border-radius:10px;font-size:11px">${op}</span>`).join("")}</div><div style="font-size:11px;color:#6b7280">${mode === "enforce" ? "Violations will be blocked" : mode === "report" ? "Violations logged but allowed" : "Both enforcement and reporting"}</div>${requireForScript ? '<div style="font-size:11px;color:#6b7280;margin-top:4px">With require-trusted-types-for \'script\'</div>' : ""}</div>`;return { output: lines.join("\n"), preview };}};